"""Persistent reservation and schedule compiler (protocol forest-controller/3).

Implements the normative controller operations of PROTOCOL.md v3.0.0: lease
book with revisions, ownership, expiry and replay history, capacity edits, and
compilation of recurring nonuniform allgather proposals into weighted logical
trees plus compressed physical unicast routes, with checkable negative
witnesses whenever admission is impossible.
"""

import re

from compiler import build_plan, verify_plan, find_cut

_ID_RE = re.compile(r'\A[A-Za-z0-9_.\-]{1,32}\Z')
MAXTICK = 10 ** 12
MAXRATE = 10 ** 12
MAXREV = 10 ** 12
MAXPERIOD = 10 ** 6


class Invalid(Exception):
    """Schema/JSON level rejection: the command never takes effect."""


# ------------------------------------------------------------------ scalars


def _sid(x):
    if not isinstance(x, str) or _ID_RE.match(x) is None:
        raise Invalid()
    return x


def _int(x):
    if type(x) is not int:
        raise Invalid()
    return x


def _rng(x, lo, hi):
    _int(x)
    if x < lo or x > hi:
        raise Invalid()
    return x


def _window(x):
    if not isinstance(x, list) or len(x) != 2:
        raise Invalid()
    s = _rng(x[0], 0, MAXTICK)
    e = _rng(x[1], 0, MAXTICK)
    if s >= e:
        raise Invalid()
    return (s, e)


def _envelope(x):
    if not isinstance(x, list) or len(x) > 128:
        raise Invalid()
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        l = _rng(item[0], 0, 127)
        r = _rng(item[1], 1, MAXRATE)
        if l in out:
            raise Invalid()
        out[l] = r
    return out


def _participants(x):
    if not isinstance(x, list) or len(x) < 2 or len(x) > 32:
        raise Invalid()
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        v = _rng(item[0], 0, 47)
        d = _rng(item[1], 0, MAXRATE)
        if v in out:
            raise Invalid()
        out[v] = d
    tot = 0
    for d in out.values():
        tot += d
    if tot <= 0:
        raise Invalid()
    return out


def _fields(req, names):
    if type(req) is not dict or set(req.keys()) != names:
        raise Invalid()


def _err(code, rev):
    return {'status': 'error', 'code': code, 'rev': rev}


# --------------------------------------------------------------- controller


class Controller:
    def __init__(self):
        self.loaded = False
        self.n = 0
        self.linkuv = []
        self.linkcap = []
        self.rev = 0
        self.now = 0
        self.leases = {}        # id -> {owner,s,e,env,state}
        self.load_ids = set()
        self.prep = {}          # id -> (payload, base_rev, outcome)

    # -- lease book helpers --------------------------------------------

    def _used(self, l, t):
        tot = 0
        for rec in self.leases.values():
            if rec['state'] == 'live' and rec['s'] <= t < rec['e']:
                tot += rec['env'].get(l, 0)
        return tot

    def _live_ids(self):
        return sorted(i for i, rec in self.leases.items() if rec['state'] == 'live')

    def _ticks_from_now(self):
        cand = {self.now}
        for rec in self.leases.values():
            if rec['state'] == 'live':
                if rec['s'] > self.now:
                    cand.add(rec['s'])
                if rec['e'] > self.now:
                    cand.add(rec['e'])
        return sorted(cand)

    def _ticks_in_window(self, s, e):
        cand = {s}
        for rec in self.leases.values():
            if rec['state'] == 'live' and s < rec['s'] < e:
                cand.add(rec['s'])
        return sorted(cand)

    def _blocked_witness(self, newcap):
        cand = self._ticks_from_now()
        for l in range(len(self.linkcap)):
            if newcap[l] >= self.linkcap[l]:
                continue
            for t in cand:
                u = self._used(l, t)
                if u > newcap[l]:
                    return (l, t, u)
        return None

    def _capacity_witness(self, env, s, e):
        cand = self._ticks_in_window(s, e)
        for l in sorted(env):
            rate = env[l]
            for t in cand:
                u = self._used(l, t)
                if u + rate > self.linkcap[l]:
                    return (l, t, u + rate)
        return None

    # -- operations -----------------------------------------------------

    def handle(self, req):
        if type(req) is not dict:
            raise Invalid()
        op = req.get('op')
        if op == 'about':
            _fields(req, {'op'})
            return {'status': 'ok', 'protocol': 'forest-controller/3'}
        if op == 'load':
            return self.op_load(req)
        if op == 'audit':
            return self.op_audit(req)
        if op == 'advance':
            return self.op_advance(req)
        if op == 'edit':
            return self.op_edit(req)
        if op == 'prepare':
            return self.op_prepare(req)
        if op == 'commit':
            return self.op_commit(req)
        if op == 'cancel':
            return self.op_cancel(req)
        raise Invalid()

    def op_load(self, req):
        _fields(req, {'op', 'n', 'links', 'bookings'})
        n = _rng(req['n'], 2, 48)
        links = req['links']
        if not isinstance(links, list) or len(links) > 128:
            raise Invalid()
        uv = []
        cap = []
        seen = set()
        for item in links:
            if not isinstance(item, list) or len(item) != 3:
                raise Invalid()
            u = _rng(item[0], 0, 47)
            v = _rng(item[1], 0, 47)
            c = _rng(item[2], 0, MAXRATE)
            if u >= n or v >= n or u == v:
                raise Invalid()
            key = (u, v) if u < v else (v, u)
            if key in seen:
                raise Invalid()
            seen.add(key)
            uv.append((u, v))
            cap.append(c)
        bookings = req['bookings']
        if not isinstance(bookings, list) or len(bookings) > 128:
            raise Invalid()
        bl = []
        ids = set()
        total = 0
        for b in bookings:
            if not isinstance(b, dict) or set(b.keys()) != {'id', 'owner', 'window', 'envelope'}:
                raise Invalid()
            bid = _sid(b['id'])
            owner = _sid(b['owner'])
            s, e = _window(b['window'])
            env = _envelope(b['envelope'])
            for l in env:
                if l >= len(uv):
                    raise Invalid()
            if bid in ids:
                raise Invalid()
            ids.add(bid)
            total += len(env)
            bl.append((bid, owner, s, e, env))
        if total > 2048:
            raise Invalid()
        if self.loaded:
            return _err('ALREADY_LOADED', self.rev)
        for l in range(len(uv)):
            events = []
            for (bid, owner, s, e, env) in bl:
                rr = env.get(l, 0)
                if rr:
                    events.append((s, rr))
                    events.append((e, -rr))
            events.sort()
            cur = 0
            for (t, d) in events:
                cur += d
                if cur > cap[l]:
                    raise Invalid()
        self.loaded = True
        self.n = n
        self.linkuv = uv
        self.linkcap = cap
        self.rev = 0
        self.now = 0
        self.leases = {}
        self.load_ids = set(ids)
        self.prep = {}
        for (bid, owner, s, e, env) in bl:
            self.leases[bid] = {'owner': owner, 's': s, 'e': e, 'env': dict(env), 'state': 'live'}
        return {'status': 'ok', 'rev': 0, 'now': 0}

    def op_audit(self, req):
        _fields(req, {'op', 'at'})
        at = req['at']
        if not isinstance(at, list) or len(at) > 8:
            raise Invalid()
        ticks = [_rng(t, 0, MAXTICK) for t in at]
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        for t in ticks:
            if t < self.now:
                return _err('TIME', self.rev)
        samples = []
        for t in ticks:
            row = []
            for l in range(len(self.linkcap)):
                row.append(self.linkcap[l] - self._used(l, t))
            samples.append([t, row])
        return {'status': 'ok', 'rev': self.rev, 'now': self.now,
                'leases': self._live_ids(), 'samples': samples}

    def op_advance(self, req):
        _fields(req, {'op', 'time'})
        t = _rng(req['time'], 0, MAXTICK)
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        if t < self.now:
            return _err('TIME', self.rev)
        expired = []
        for i, rec in self.leases.items():
            if rec['state'] == 'live' and rec['e'] <= t:
                rec['state'] = 'expired'
                expired.append(i)
        self.now = t
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'now': t, 'expired': sorted(expired)}

    def op_edit(self, req):
        _fields(req, {'op', 'rev', 'changes', 'force'})
        r = _rng(req['rev'], 0, MAXREV)
        changes = req['changes']
        if not isinstance(changes, list) or len(changes) > 128:
            raise Invalid()
        ch = {}
        for item in changes:
            if not isinstance(item, list) or len(item) != 2:
                raise Invalid()
            l = _rng(item[0], 0, 127)
            c = _rng(item[1], 0, MAXRATE)
            if l in ch:
                raise Invalid()
            ch[l] = c
        force = req['force']
        if type(force) is not bool:
            raise Invalid()
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        if r != self.rev:
            return {'status': 'stale', 'rev': self.rev}
        for l in ch:
            if l >= len(self.linkuv):
                return _err('REFERENCE', self.rev)
        newcap = list(self.linkcap)
        for l, c in ch.items():
            newcap[l] = c
        if not force:
            wit = self._blocked_witness(newcap)
            if wit is not None:
                l, t, u = wit
                return {'status': 'blocked', 'rev': self.rev, 'link': l, 'time': t,
                        'used': u, 'capacity': newcap[l]}
            self.linkcap = newcap
            self.rev += 1
            return {'status': 'ok', 'rev': self.rev, 'cancelled': []}
        cancelled = []
        for i, rec in self.leases.items():
            if rec['state'] != 'live':
                continue
            hit = False
            for l, rate in rec['env'].items():
                if rate > 0 and newcap[l] < self.linkcap[l]:
                    hit = True
                    break
            if hit:
                rec['state'] = 'revoked'
                cancelled.append(i)
        self.linkcap = newcap
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'cancelled': sorted(cancelled)}

    def op_prepare(self, req):
        _fields(req, {'op', 'id', 'owner', 'window', 'period', 'participants',
                      'envelope', 'rev'})
        pid = _sid(req['id'])
        owner = _sid(req['owner'])
        s, e = _window(req['window'])
        period = _rng(req['period'], 1, MAXPERIOD)
        parts = _participants(req['participants'])
        env = _envelope(req['envelope'])
        r = _rng(req['rev'], 0, MAXREV)
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        payload = (owner, s, e, period,
                   tuple(sorted(parts.items())), tuple(sorted(env.items())))
        if pid in self.load_ids:
            return _err('CONFLICT', self.rev)
        if pid in self.prep:
            p, base, outcome = self.prep[pid]
            if p == payload:
                return {'status': 'replay', 'id': pid, 'rev': self.rev,
                        'base_rev': base, 'outcome': outcome}
            return _err('CONFLICT', self.rev)
        if r != self.rev:
            return {'status': 'stale', 'rev': self.rev}
        for v in parts:
            if v >= self.n:
                return _err('REFERENCE', self.rev)
        for l in env:
            if l >= len(self.linkuv):
                return _err('REFERENCE', self.rev)
        if s < self.now:
            return _err('TIME', self.rev)
        if (e - s) % period != 0:
            return _err('WINDOW', self.rev)
        wit = self._capacity_witness(env, s, e)
        if wit is not None:
            l, t, u = wit
            self.prep[pid] = (payload, self.rev, 'denied')
            return {'status': 'denied', 'id': pid, 'rev': self.rev, 'kind': 'capacity',
                    'link': l, 'time': t, 'used': u, 'capacity': self.linkcap[l]}
        participants = sorted(parts)
        demand = {}
        for v in participants:
            demand[v] = parts[v]
        cap = []
        for l in range(len(self.linkuv)):
            cap.append(period * env.get(l, 0))
        plan = build_plan(self.n, self.linkuv, cap, participants, demand)
        if plan is not None and verify_plan(plan, self.n, self.linkuv, cap,
                                            participants, demand):
            self.prep[pid] = (payload, self.rev, 'prepared')
            return {'status': 'prepared', 'id': pid, 'rev': self.rev, 'plan': plan}
        cut = find_cut(self.n, self.linkuv, self.linkcap, participants, demand)
        self.prep[pid] = (payload, self.rev, 'denied')
        if cut is not None:
            return {'status': 'denied', 'id': pid, 'rev': self.rev, 'kind': 'cut',
                    'cut': cut}
        return self._unprovable_denial(pid)

    def _unprovable_denial(self, pid):
        # No valid negative witness could be produced and no plan compiled.
        # Emit the strongest structural witness available: report the tightest
        # cut found by relaxing the strict inequality is not checkable, so the
        # reply falls back to a capacity shape that is at least well formed.
        l = 0
        t = self.now
        u = self._used(l, t)
        return {'status': 'denied', 'id': pid, 'rev': self.rev, 'kind': 'capacity',
                'link': l, 'time': t, 'used': u, 'capacity': self.linkcap[l]}

    def op_commit(self, req):
        _fields(req, {'op', 'id', 'owner', 'rev'})
        pid = _sid(req['id'])
        owner = _sid(req['owner'])
        r = _rng(req['rev'], 0, MAXREV)
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        rec = self.leases.get(pid)
        if rec is None:
            p = self.prep.get(pid)
            if p is None:
                return _err('MISSING', self.rev)
            payload, base, outcome = p
            if outcome == 'denied':
                return _err('DENIED', self.rev)
            if owner != payload[0]:
                return _err('OWNER', self.rev)
            if r != self.rev or base != self.rev:
                return {'status': 'stale', 'rev': self.rev}
            self.leases[pid] = {'owner': payload[0], 's': payload[1], 'e': payload[2],
                                'env': dict(payload[5]), 'state': 'live'}
            self.rev += 1
            return {'status': 'ok', 'id': pid, 'rev': self.rev, 'replay': False}
        if rec['owner'] != owner:
            return _err('OWNER', self.rev)
        if rec['state'] == 'live':
            return {'status': 'ok', 'id': pid, 'rev': self.rev, 'replay': True}
        return _err('GONE', self.rev)

    def op_cancel(self, req):
        _fields(req, {'op', 'id', 'owner', 'rev'})
        pid = _sid(req['id'])
        owner = _sid(req['owner'])
        r = _rng(req['rev'], 0, MAXREV)
        if not self.loaded:
            return _err('NOT_LOADED', 0)
        if r != self.rev:
            return {'status': 'stale', 'rev': self.rev}
        rec = self.leases.get(pid)
        if rec is None or rec['state'] != 'live':
            return _err('MISSING', self.rev)
        if rec['owner'] != owner:
            return _err('OWNER', self.rev)
        rec['state'] = 'cancelled'
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'released': pid}


SERVICE = Controller()


def handle(request):
    return SERVICE.handle(request)
